<?php $rows=$rows??[];$counts=array_count_values(array_column($rows,'status')); ?>
<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb"><a href="<?=url('/admin/dashboard')?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Attendance</span></nav><h1>Students Attendance Record</h1><p>Review persisted attendance by date range and class.</p></div></header>
<form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label for="from">From Date</label><input class="module-input" id="from" name="from" type="date" value="<?=e($from)?>"></div><div class="module-field"><label for="to">To Date</label><input class="module-input" id="to" name="to" type="date" value="<?=e($to)?>"></div><div class="module-field"><label for="class">Class</label><select class="module-input" id="class" name="class"><option value="0">All classes</option><?php foreach($classes as$c):?><option value="<?=$c['id']?>" <?=$selectedClass===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></div><div class="filter-actions"><button class="btn btn--primary">Apply</button></div></form>
<div class="metric-grid"><div class="metric-card"><span>Total Records</span><strong><?=count($rows)?></strong></div><div class="metric-card"><span>Present</span><strong><?=$counts['Present']??0?></strong></div><div class="metric-card"><span>On Leave</span><strong><?=$counts['Leave']??0?></strong></div><div class="metric-card"><span>Absent</span><strong><?=$counts['Absent']??0?></strong></div></div>
